package com.hotelmanagement.hms.maintenance.web; import com.hotelmanagement.hms.maintenance.dto.*; import com.hotelmanagement.hms.maintenance.model.*; import com.hotelmanagement.hms.maintenance.service.*; import com.hotelmanagement.hms.shared.web.PageResponse; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*; import org.springframework.http.HttpStatus; import java.util.*; @RestController @RequestMapping("/api/v1/hotels/{hotel}/branches/{branch}/maintenance") public class MaintenanceController {private final MaintenanceService s;public MaintenanceController(MaintenanceService s){this.s=s;} @PostMapping @ResponseStatus(HttpStatus.CREATED) public MaintenanceResponse create(@PathVariable UUID hotel,@PathVariable UUID branch,@Valid @RequestBody MaintenanceRequest r){return s.create(hotel,branch,r);} @GetMapping public PageResponse<MaintenanceResponse> list(@PathVariable UUID hotel,@PathVariable UUID branch,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="50")int size){return s.list(hotel,branch,page,size);} @PutMapping("/{id}/{status}") public MaintenanceResponse update(@PathVariable UUID hotel,@PathVariable UUID branch,@PathVariable UUID id,@PathVariable MaintenanceStatus status){return s.update(hotel,branch,id,status);}}
